 더 빠르고 효율적인 앱 개발과 유지 관리를 가능하게 합니다. 실습과 함께 PWA의 개념, 장점, 구현 방법을 단계별로 학습하며, 실무에 바로 적용할 수 있는 역량을 갖추게 됩니다.',1,0,NULL,'[-0.0007840959005989134, 0.03195581212639809, 0.019589392468333244, -0.02766675502061844, 0.01834277994930744, -0.051098983734846115, -0.03943043574690819, 0.07315048575401306, -0.013516612350940704, 0.009037832729518414, 0.09973422437906265, 0.012513420544564724, 0.03842239826917648, -0.02633405290544033, 0.12184230983257294, -0.04541916772723198, 0.03087853454053402, 0.011121704243123531, -0.05194491147994995, 0.061016764491796494, 0.017703108489513397, -0.10872979462146759, -0.011232348158955574, -0.07290159910917282, -0.025609450414776802, -0.0026598619297146797, -0.020889662206172943, 0.06162546947598457, 0.027800973504781723, 0.009380246512591839, -0.06942254304885864, 0.024268798530101776, -0.019062498584389687, -0.011008941568434238, -0.08464637398719788, 0.01547835860401392, -0.02326122671365738, -0.0010928040137514472, -0.04661359265446663, -0.019494127482175827, -0.08650784194469452, -0.09188486635684967, 0.0014800503849983215, -0.0492561012506485, 0.04452474042773247, -0.022387467324733734, -0.00966266542673111, -0.013358249329030514, -0.13468074798583984, -0.041280511766672134, -0.03336044400930405, -0.033008873462677, 0.008067506365478039, -0.05657658725976944, -0.02279052883386612, -0.08159289509057999, 0.00609323475509882, 0.014392219483852386, 0.031021414324641228, 0.03242209553718567, -0.04255970939993858, 0.05407004430890083, -0.011065243743360043, 0.04250023141503334, 0.11826823651790619, 0.026710262522101402, 0.0012112619588151574, -0.062153108417987823, -0.015729688107967377, 0.026580022647976875, 0.002559803193435073, 4.3267689761705697e-05, -0.03014742210507393, -0.004844787064939737, -0.07132026553153992, -0.0800466239452362, 0.04099845513701439, 0.014872987754642963, -0.09867111593484879, -0.020843546837568283, 0.04690112918615341, 0.006616763770580292, 0.019477112218737602, -0.026240333914756775, -0.0832950621843338, 0.005305407