DROP TABLE IF EXISTS `alert`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `alert` (
  `alert_no` int NOT NULL AUTO_INCREMENT COMMENT '알림 고유번호',
  `id` varchar(50) NOT NULL COMMENT '알림을 받는 사람 ID (user.id 참조)',
  `alert_id` varchar(50) NOT NULL COMMENT '알림을 발생시킨 ID (user.id 참조)',
  `alert_type` int NOT NULL COMMENT '알림 종류 (1:댓글, 2:좋아요, 3:팔로우, 4:답변 채택, 5:기타)',
  `alert_content` text COMMENT '알림 내용',
  `alerted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '알림 발생 일시',
  `target_board_no` int DEFAULT NULL COMMENT '알림 클릭시 이동할 게시글 고유번호 (board.board_no 참조)',
  `target_comment_answer_no` int DEFAULT NULL COMMENT '알림 클릭시 이동할 댓글/답변 고유번호 (comment_answer.comment_answer_no 참조)',
  PRIMARY KEY (`alert_no`),
  KEY `fk_alert_receiver_id` (`id`),
  KEY `fk_alert_sender_id` (`alert_id`),
  KEY `fk_alert_board_no` (`target_board_no`),
  KEY `fk_alert_comment_no` (`target_comment_answer_no`),
  CONSTRAINT `fk_alert_board_no` FOREIGN KEY (`target_board_no`) REFERENCES `board` (`board_no`),
  CONSTRAINT `fk_alert_comment_no` FOREIGN KEY (`target_comment_answer_no`) REFERENCES `comment_answer` (`comment_answer_no`),
  CONSTRAINT `fk_alert_receiver_id` FOREIGN KEY (`id`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_alert_sender_id` FOREIGN KEY (`alert_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

