DROP TABLE IF EXISTS `block`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `block` (
  `blocker_id` varchar(50) NOT NULL COMMENT '차단한 사용자 ID (user.id 참조)',
  `blocked_id` varchar(50) NOT NULL COMMENT '차단당한 사용자 ID (user.id 참조)',
  `blocked_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '차단 설정 일시',
  PRIMARY KEY (`blocker_id`,`blocked_id`),
  KEY `fk_block_blocked_id` (`blocked_id`),
  CONSTRAINT `fk_block_blocked_id` FOREIGN KEY (`blocked_id`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_block_blocker_id` FOREIGN KEY (`blocker_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

