--
-- Table structure for table `board`
--

DROP TABLE IF EXISTS `board`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `board` (
  `board_no` int NOT NULL AUTO_INCREMENT COMMENT '게시글 고유번호',
  `id` varchar(50) NOT NULL COMMENT '작성자 아이디 (user.id 참조)',
  `board_title` varchar(255) NOT NULL COMMENT '글 제목',
  `board_content` text NOT NULL COMMENT '글 내용',
  `board_category` int DEFAULT NULL COMMENT '글 카테고리 1: 자유 2:Q&A 3:코딩테스트 4:공지사항 5:이용약관 6:개인정보처리방침',
  `hit` int NOT NULL DEFAULT '0' COMMENT '조회수',
  `board_like` int NOT NULL DEFAULT '0' COMMENT '추천수',
  `board_dislike` int NOT NULL DEFAULT '0' COMMENT '비추천수',
  `board_created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '작성일시',
  `board_updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '수정일시',
  `board_deleted` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`board_no`),
  KEY `id` (`id`),
  CONSTRAINT `board_ibfk_1` FOREIGN KEY (`id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=236 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

