--
-- Table structure for table `board_view_log`
--

DROP TABLE IF EXISTS `board_view_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `board_view_log` (
  `log_id` int NOT NULL AUTO_INCREMENT COMMENT '게시글 조회 로그 고유번호',
  `user_id` varchar(50) NOT NULL COMMENT '조회한 사용자 아이디 (user.id 참조)',
  `board_no` int NOT NULL COMMENT '조회한 게시글 번호 (board.board_no 참조)',
  `viewed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '조회 일시',
  PRIMARY KEY (`log_id`),
  KEY `idx_view_user_id` (`user_id`),
  KEY `idx_view_board_no` (`board_no`),
  CONSTRAINT `fk_view_board_no` FOREIGN KEY (`board_no`) REFERENCES `board` (`board_no`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_view_user_id` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=230 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

