CREATE TABLE `chat` (
  `chat_no` int NOT NULL AUTO_INCREMENT COMMENT '채팅 고유번호',
  `id` varchar(50) NOT NULL COMMENT '채팅 작성자 아이디 (user.id 참조)',
  `chat_content` text NOT NULL COMMENT '채팅 내용',
  `chat_created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '작성일시',
  PRIMARY KEY (`chat_no`),
  KEY `fk_chat_user_id` (`id`),
  CONSTRAINT `fk_chat_user_id` FOREIGN KEY (`id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
