DROP TABLE IF EXISTS `file`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `file` (
  `file_no` int NOT NULL AUTO_INCREMENT COMMENT '파일고유번호',
  `logical_file_name` varchar(255) NOT NULL COMMENT '논리파일명',
  `physical_file_name` varchar(255) NOT NULL COMMENT '물리파일명',
  `file_size` bigint NOT NULL COMMENT '파일 크기 (Byte 단위)',
  `file_ext` varchar(10) NOT NULL COMMENT '파일 확장자',
  `board_no` int NOT NULL COMMENT '게시글 고유번호 (board.board_no 참조)',
  PRIMARY KEY (`file_no`),
  KEY `fk_file_board_no` (`board_no`),
  CONSTRAINT `fk_file_board_no` FOREIGN KEY (`board_no`) REFERENCES `board` (`board_no`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
