DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `id` varchar(50) NOT NULL COMMENT '아이디',
  `name` varchar(50) DEFAULT NULL COMMENT '이름',
  `nick` varchar(50) NOT NULL COMMENT '닉네임',
  `email` varchar(255) NOT NULL COMMENT '이메일',
  `password` varchar(255) NOT NULL COMMENT '비밀번호',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '가입일시',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '수정일시',
  `last_login_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '마지막 로그인',
  `user_type` int NOT NULL DEFAULT '2' COMMENT '1:관리자 2:일반회원 3:차단회원',
  `icon` varchar(255) DEFAULT NULL COMMENT '유저 아이콘',
  `background_img` varchar(255) DEFAULT NULL COMMENT '배경 이미지',
  `insignia` varchar(255) DEFAULT NULL COMMENT '휘장',
  `withdraw_at` datetime DEFAULT NULL COMMENT '탈퇴일시',
  `withdraw` tinyint(1) NOT NULL DEFAULT '0' COMMENT '탈퇴여부',
  `user_current_point` int NOT NULL DEFAULT '0' COMMENT '현재 잔여 포인트',
  PRIMARY KEY (`id`),
  UNIQUE KEY `nick` (`nick`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
